STAGE_NAME = #{stageName}, SORT_NO = #{sortNo}, STATUS = #{status}, FINAL_REQUIRED = #{finalRequired}, RELEASE_ON_PASS = #{releaseOnPass}, JUDGE_USER_ID = #{judgeUserId}, JUDGE_USER_NAME = #{judgeUserName}, JUDGE_TIME = #{judgeTime}, COMMENT_TEXT = #{commentText}, UPDATE_TIME = #{updateTime}
